  "Sem terminal no timelapse: a conversa é a de agora, não a do momento reproduzido.": "타임랩스에서는 터미널을 쓸 수 없어요: 대화는 재생 중인 시점이 아니라 지금 것이에요.",
  "O agente já saiu do escritório.": "에이전트가 이미 사무실을 나갔어요.",
  "Ver a conversa desta sessão como no {0}, ao vivo{1} (T)": "이 세션의 대화를 {0}처럼 실시간으로 보기{1} (T)",
  "terminal do Claude Code": "Claude Code 터미널",
  "; \"Assumir daqui\" continua nela aqui": "; \"여기서 이어받기\"로 여기서 이어 갈 수 있어요",
  "Abrir o terminal desta sessão, que roda aqui no Habblaud (T)": "이 세션의 터미널 열기(Habblaud 안에서 실행 중) (T)",
  "Abrir o terminal: a sessão roda em outro terminal; dá para assumir daqui (T)": "터미널 열기: 세션이 다른 터미널에서 실행 중이에요. 여기서 이어받을 수 있어요 (T)",
  "Aprovações": "승인",
  "Em segundo plano": "백그라운드",
  "Renomear sala": "방 이름 바꾸기",
  "Levar a câmera até a sala": "카메라를 방으로 이동",
  "Esta sala foi fechada: todos os agentes saíram.": "이 방은 닫혔어요: 에이전트가 모두 나갔어요.",
  "Ninguém na sala agora.": "지금 방에 아무도 없어요.",
  "Agentes": "에이전트",
  "Progresso das tarefas da sala": "방 작업 진행률",
  "Atividade recente": "최근 활동",
  "Copiar caminho": "경로 복사",
