  "Terminou o turno e está esperando {0} shells terminarem. A cada um que termina, o agente recebe o resultado.": "턴을 마치고 셸 {0}개가 끝나길 기다리는 중이에요. 하나씩 끝날 때마다 에이전트가 결과를 받아요.",
  "Terminou o turno e está esperando o shell terminar. Quando ele terminar, o agente recebe o resultado.": "턴을 마치고 셸이 끝나길 기다리는 중이에요. 끝나면 에이전트가 결과를 받아요.",
