  "Até 3 min: recosta na cadeira com um balde de pipoca e assiste ao terminal como se fosse um filme.": "3분까지: 팝콘 한 통을 들고 의자에 기대 영화 보듯 터미널을 봐요.",
  "A pipoca acabou: girando na cadeira": "팝콘 다 먹음: 의자 빙글빙글",
  "De 3 a 10 min: a pipoca acaba; braços cruzados, dedos batendo e, de vez em quando, um giro completo na cadeira.": "3~10분: 팝콘이 떨어져요. 팔짱 끼고 손가락을 톡톡, 가끔 의자를 한 바퀴 돌려요.",
  "Já tem teia de aranha na cadeira": "의자에 벌써 거미줄이",
