  "Este subagente roda em segundo plano: o terminal só mostra o pedido depois que você responder aqui ou escolher “Responder no terminal”.": "이 서브에이전트는 백그라운드에서 돌아요: 여기서 답하거나 “터미널에서 답하기”를 고르기 전까지 터미널에 요청이 안 보여요.",
