  "ao vivo (mod do Habblaud)": "실시간 (Habblaud mod)",
  "Recomendado: instala o mod do Habblaud no Claude Code (2.1.287 ou mais novo), que passa o uso de 5 h e da semana ao vivo. Rode na pasta do Habblaud, no computador onde o Claude Code roda; nas sessões já abertas, `/reload-plugins`.": "추천: Claude Code(2.1.287 이상)에 Habblaud mod를 설치해요. 5시간·주간 사용량을 실시간으로 보내 줘요. Claude Code가 도는 컴퓨터의 Habblaud 폴더에서 실행하고, 이미 열린 세션에서는 `/reload-plugins`를 실행하세요.",
  "No Claude Code anterior ao 2.1.287: liga um tap na linha de status, que passa os mesmos números ao vivo.": "2.1.287보다 오래된 Claude Code: 상태 줄에 tap을 걸어 같은 숫자를 실시간으로 보내요.",
