  "o Habblaud não respondeu em {0} s. Veja o que aconteceu com: npm run docker:logs": "Habblaud가 {0}초 안에 응답하지 않았어요. 원인 확인: npm run docker:logs",
  "Habblaud{0} no ar: {1}": "Habblaud{0} 실행 중: {1}",
  "sessão aberta": "열린 세션",
  "sessões abertas": "열린 세션",
  "erro ao ler ({0})": "읽기 오류({0})",
  "  Conta {0} ({1}): {2}{3}": "  계정 {0}({1}): {2}{3}",
  "  Sobrou do CodeTown; depois de conferir o escritório, apague com: {0}": "  CodeTown에서 남은 것이에요. 사무실을 확인한 뒤 지우세요: {0}",
  "  Logs: npm run docker:logs · Parar: npm run docker:down": "  로그: npm run docker:logs · 중지: npm run docker:down",
