  // scripts/hooks-install.ts
  "Aguardando resposta no Habblaud": "Habblaud에서 응답 기다리는 중",
  "Uso: npm run hooks:<install|uninstall|status> [-- opções]\n\n  install     acrescenta o hook de permissão do Habblaud em cada conta (faz backup do settings.json)\n  uninstall   tira o hook do Habblaud de cada conta (os outros hooks ficam)\n  status      mostra se o hook está instalado e se o Habblaud está respondendo pedidos\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no hook (padrão: detectado no PATH)\n  --port <n>       porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --timeout <s>    quanto o hook espera sua resposta no Habblaud antes de devolver o pedido ao terminal\n                   (padrão: {1} s)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS).": "사용법: npm run hooks:<install|uninstall|status> [-- 옵션]\n\n  install     각 계정에 Habblaud 권한 훅을 추가해요(settings.json 백업)\n  uninstall   각 계정에서 Habblaud 훅을 빼요(다른 훅은 그대로)\n  status      훅이 설치됐는지, Habblaud가 요청에 응답하는지 보여 줘요\n\n옵션:\n  --dry-run        아무것도 쓰지 않고 바뀔 내용만 보여 줘요\n  --node <cmd>     훅에서 쓸 node 명령(기본값: PATH 에서 찾음)\n  --port <n>       Habblaud 포트(기본값: HABBLAUD_PORT 또는 {0})\n  --timeout <s>    요청을 터미널로 돌려보내기 전에 훅이 Habblaud에서 답을 기다리는 시간\n                   (기본값: {1}초)\n  -h, --help       이 도움말을 보여 줘요\n\n계정: 서버와 같아요(projects/ 나 sessions/ 가 있는 ~/.claude*, CLAUDE_CONFIG_DIR 또는\nHABBLAUD_CLAUDE_DIRS).",
  "atualizado (novo caminho do Habblaud, do node ou das opções)": "업데이트됨(Habblaud 경로, node 경로 또는 옵션이 바뀜)",
  "instalado": "설치됨",
  "hook do Habblaud removido": "Habblaud 훅 제거됨",
  "--node precisa de um caminho.": "--node 에는 경로가 필요해요.",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use HABBLAUD_CLAUDE_DIRS se estiverem em outro lugar.": "Claude Code 계정을 찾지 못했어요(projects/ 나 sessions/ 가 있는 ~/.claude*). 다른 곳에 있다면 HABBLAUD_CLAUDE_DIRS 를 쓰세요.",
  " (esse arquivo não existe mais: o hook falha e vale só o terminal)": " (이 파일이 더 이상 없어요: 훅이 실패하고 터미널에서만 답할 수 있어요)",
  "! {0}: o hook aponta para {1}{2}; rode npm run hooks:install para atualizar": "! {0}: 훅이 {1}{2}을(를) 가리켜요. 업데이트하려면 npm run hooks:install 을 실행하세요",
  "• {0}: instalado ({1}; tempo limite {2} s)": "• {0}: 설치됨({1}, 제한 시간 {2}초)",
  "Habblaud em http://127.0.0.1:{0}: fora do ar (com ele parado, o hook sai na hora e o terminal segue normal).": "Habblaud(http://127.0.0.1:{0}): 꺼져 있음(꺼져 있는 동안 훅은 바로 끝나고 터미널은 평소처럼 동작해요).",
  "Habblaud em http://127.0.0.1:{0}: respondendo pedidos de permissão (com alguma página aberta).": "Habblaud(http://127.0.0.1:{0}): 권한 요청에 응답 중(열린 페이지가 있을 때).",
  "Habblaud em http://127.0.0.1:{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "Habblaud(http://127.0.0.1:{0}): 켜져 있지만 사무실에서 답하기는 꺼져 있어요(포트가 네트워크에 노출됐거나 HABBLAUD_TERMINAL=0).",
  "Pronto. Com o Habblaud aberto no navegador, os pedidos de permissão aparecem no escritório e você": "완료. 브라우저에 Habblaud를 열어 두면 권한 요청이 사무실에 나타나고",
  "pode aprovar ou recusar por lá; o diálogo continua no terminal e vale o que responder primeiro.": "거기서 승인하거나 거절할 수 있어요. 대화상자는 터미널에도 남고, 먼저 온 답이 적용돼요.",
  "Sessões abertas costumam recarregar o settings.json sozinhas; se não, reabra a sessão.": "열린 세션은 보통 settings.json 을 알아서 다시 읽어요. 안 되면 세션을 다시 여세요.",
  "Para desfazer: npm run hooks:uninstall": "되돌리기: npm run hooks:uninstall",
  "[hooks] Erro: {0}": "[hooks] 오류: {0}",
  "[hooks] Erro inesperado: {0}": "[hooks] 예상치 못한 오류: {0}",

  // scripts/mod-install.ts
  "Uso: npm run mod:<install|uninstall|status> [-- opções]\n\n  install     instala o mod do Habblaud no Claude Code de cada conta (marketplace desta pasta + plugins)\n              e tira o que ele substitui: o tap de statusline e o hook de permissão antigos e o mod do\n              nome antigo (codetown)\n  uninstall   tira os plugins e o marketplace do Habblaud de cada conta (e os do nome antigo, se sobraram)\n  status      mostra, por conta, o marketplace, os plugins (e versões) e o que sobrou do jeito antigo\n\nOpções:\n  --sem-permissoes   não instala o plugin de responder permissões pelo escritório (e mantém o hook antigo)\n  --sem-mensagens    não instala o plugin de mandar mensagens pelo escritório (um já instalado continua)\n  --conta <pasta>    só esta conta (ex.: --conta ~/.claude-conta2); pode repetir\n  --dry-run          mostra o que faria, sem instalar nem gravar nada\n  --claude <cmd>     comando do Claude Code (padrão: claude, do PATH)\n  -h, --help         mostra esta ajuda\n\nPrecisa do Claude Code {0} ou mais novo. Em versões anteriores, use o jeito antigo:\nnpm run usage:install (uso ao vivo) e npm run hooks:install (responder permissões); mandar mensagens pelo\nescritório só existe com o mod.\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "사용법: npm run mod:<install|uninstall|status> [-- 옵션]\n\n  install     각 계정의 Claude Code에 Habblaud mod를 설치하고(이 폴더의 marketplace + 플러그인)\n              mod가 대신하는 것을 빼요: 예전 statusline tap, 예전 권한 훅, 예전 이름(codetown)의\n              mod\n  uninstall   각 계정에서 Habblaud 플러그인과 marketplace를 빼요(예전 이름의 것이 남아 있으면 그것도)\n  status      계정별로 marketplace, 플러그인(과 버전), 예전 방식에서 남은 것을 보여 줘요\n\n옵션:\n  --sem-permissoes   사무실에서 권한에 답하는 플러그인을 설치하지 않아요(예전 훅은 유지)\n  --sem-mensagens    사무실에서 메시지를 보내는 플러그인을 설치하지 않아요(이미 설치된 것은 유지)\n  --conta <폴더>     이 계정만(예: --conta ~/.claude-conta2), 여러 번 쓸 수 있어요\n  --dry-run          아무것도 설치하거나 쓰지 않고 할 일만 보여 줘요\n  --claude <cmd>     Claude Code 명령(기본값: PATH 의 claude)\n  -h, --help         이 도움말을 보여 줘요\n\nClaude Code {0} 이상이 필요해요. 이전 버전에서는 예전 방식을 쓰세요:\nnpm run usage:install(실시간 사용량)과 npm run hooks:install(권한 응답). 사무실에서 메시지 보내기는\nmod로만 돼요.\n\n계정: 서버와 같아요(projects/ 나 sessions/ 가 있는 ~/.claude*, CLAUDE_CONFIG_DIR 또는\nHABBLAUD_CLAUDE_DIRS). 사용량은 HABBLAUD_USAGE_DIR(기본값 ~/.habblaud/usage)에 저장돼요.",
  "o comando \"{0}\" não foi encontrado no PATH": "PATH 에서 \"{0}\" 명령을 찾지 못했어요",
  "\"{0} {1}\" não terminou em {2} s": "\"{0} {1}\" 이(가) {2}초 안에 끝나지 않았어요",
