  "tap de statusline antigo removido: o mod grava o uso no lugar dele ({0})": "예전 statusline tap 제거: 이제 mod가 대신 사용량을 기록해요({0})",
  "tap de statusline antigo: {0} (rode npm run usage:uninstall depois de conferir)": "예전 statusline tap: {0} (확인한 뒤 npm run usage:uninstall 을 실행하세요)",
