  "hook de permissão antigo removido: o plugin {0} responde no lugar dele": "예전 권한 훅 제거: 이제 {0} 플러그인이 대신 응답해요",
  "hook de permissão antigo: {0} (rode npm run hooks:uninstall depois de conferir)": "예전 권한 훅: {0} (확인한 뒤 npm run hooks:uninstall 을 실행하세요)",
  "{0}: não aparece instalado na lista do Claude Code": "{0}: Claude Code 목록에 설치된 것으로 나오지 않아요",
