  "{0}: o Claude Code registra a versão {1}, não a {2} (o manifesto em mod/ está com outra versão?)": "{0}: Claude Code에는 {2}가 아니라 {1} 버전으로 기록돼 있어요(mod/ 의 매니페스트 버전이 다른가요?)",
  "rode npm run mod:install para mandar mensagens pelo escritório (plugin {0})": "사무실에서 메시지를 보내려면 npm run mod:install 을 실행하세요(플러그인 {0})",
  "ainda com o nome antigo ({0}); o docker:up não troca sozinho: rode npm run mod:install": "아직 예전 이름이에요({0}). docker:up 은 알아서 바꾸지 않으니 npm run mod:install 을 실행하세요",
  "o mod está instalado, mas o marketplace {0} sumiu; rode npm run mod:install": "mod는 설치돼 있지만 marketplace {0}이(가) 사라졌어요. npm run mod:install 을 실행하세요",
  "o mod vem de outra pasta ({0}), então não foi atualizado; para usar esta: npm run mod:install": "mod가 다른 폴더({0})에서 와서 업데이트하지 않았어요. 이 폴더를 쓰려면: npm run mod:install",
  "marketplace {0}: catálogo relido": "marketplace {0}: 카탈로그 다시 읽음",
  "saiu com código {0}": "코드 {0}(으)로 종료됨",
  "marketplace {0}: não adicionado": "marketplace {0}: 추가 안 됨",
  "marketplace {0}: esta pasta": "marketplace {0}: 이 폴더",
  "marketplace {0}: outra origem ({1}); npm run mod:install aponta para esta pasta": "marketplace {0}: 다른 출처({1}). npm run mod:install 이 이 폴더를 가리키게 해요",
  "{0}: não instalado": "{0}: 설치 안 됨",
