  " (esta pasta: {0}; npm run mod:install ou npm run docker:up atualiza)": " (이 폴더: {0}, npm run mod:install 이나 npm run docker:up 으로 업데이트)",
  "carrega {0} de {1}": "{1}에서 {0} 불러옴",
  "esta pasta": "이 폴더",
  "! nome antigo ainda registrado: {0}; npm run mod:install troca pelo habblaud": "! 예전 이름이 아직 등록돼 있어요: {0}. npm run mod:install 이 habblaud 로 바꿔요",
  "! tap de statusline antigo ainda instalado junto com o mod: npm run mod:install tira (ou npm run usage:uninstall)": "! 예전 statusline tap 이 mod와 함께 아직 설치돼 있어요: npm run mod:install 로 빼세요(또는 npm run usage:uninstall)",
  "tap de statusline antigo instalado (jeito antigo; o mod o substitui)": "예전 statusline tap 설치됨(예전 방식, mod가 대신해요)",
  "! hook de permissão antigo ainda no settings.json junto com o plugin: os dois respondem; npm run mod:install tira (ou npm run hooks:uninstall)": "! 예전 권한 훅이 플러그인과 함께 아직 settings.json 에 있어요: 둘 다 응답해요. npm run mod:install 로 빼세요(또는 npm run hooks:uninstall)",
  "hook de permissão antigo instalado (jeito antigo; o plugin de permissões o substitui)": "예전 권한 훅 설치됨(예전 방식, 권한 플러그인이 대신해요)",
  "! disableAllHooks está ligado no settings.json desta conta: nenhum mod (nem hook) roda": "! 이 계정의 settings.json 에 disableAllHooks 가 켜져 있어요: mod도 훅도 실행되지 않아요",
  "--conta precisa da pasta da conta (ex.: --conta ~/.claude-conta2).": "--conta 에는 계정 폴더가 필요해요(예: --conta ~/.claude-conta2).",
  "--claude precisa de um comando ou caminho.": "--claude 에는 명령이나 경로가 필요해요.",
  "package.json sem \"version\" em {0}": "{0}의 package.json 에 \"version\" 이 없어요",
  "não consegui listar os marketplaces ({0})": "marketplace 목록을 가져오지 못했어요({0})",
  "não entendi a lista de marketplaces do Claude Code": "Claude Code의 marketplace 목록을 해석하지 못했어요",
  "não consegui listar os plugins ({0})": "플러그인 목록을 가져오지 못했어요({0})",
  "não entendi a lista de plugins do Claude Code": "Claude Code의 플러그인 목록을 해석하지 못했어요",
