  " · semana {0}%": " · 주간 {0}%",
  "nenhum uso capturado ainda (o Claude Code envia os limites depois da primeira resposta numa sessão aberta)": "아직 수집된 사용량이 없어요(Claude Code는 열린 세션의 첫 응답 뒤에 한도를 보내요)",
  "nenhum uso capturado": "수집된 사용량 없음",
  "Pronto. Os números aparecem no Habblaud depois da próxima resposta de cada sessão. Sessões já": "완료. 각 세션의 다음 응답 뒤에 Habblaud에 숫자가 나타나요. 이미",
  "abertas costumam recarregar o settings.json sozinhas; se o uso não aparecer, reabra a sessão.": "열린 세션은 보통 settings.json 을 알아서 다시 읽어요. 사용량이 안 보이면 세션을 다시 여세요.",
