  "Começa na hora uma sessão do Claude Code em segundo plano no computador, na pasta escolhida; as permissões chegam aqui. Pasta que o Claude Code ainda não conhece abre no app do Claude e espera o Enter lá. Anexos vão para ~/.habblaud/attachments e o pedido leva os caminhos.": "고른 폴더에서 Claude Code 세션을 컴퓨터 백그라운드로 바로 시작해요. 권한 요청은 여기로 와요. Claude Code가 아직 모르는 폴더는 Claude 앱에서 열리고 거기서 Enter를 기다려요. 첨부는 ~/.habblaud/attachments 에 저장되고 요청에 경로가 들어가요.",
