  "Sem o Codex (codex no PATH ou HABBLAUD_CODEX_BIN): só começo os agentes novos pedidos no Habblaud (http://127.0.0.1:{0}). Ctrl+C para parar.": "Codex 없음(PATH 의 codex 또는 HABBLAUD_CODEX_BIN): Habblaud(http://127.0.0.1:{0})에서 요청한 새 에이전트만 시작해요. 멈추려면 Ctrl+C.",
