  // scripts/remote-setup.ts
  "Uso: npm run remote:setup [-- opções]\n\nLiga o acesso pelo celular (https://<nome>.local) com usuário, senha e HTTPS.\n\n  --user <nome>        usuário do login (padrão: o seu usuário do sistema)\n  --name <nome>        endereço <nome>.local (padrão: habblaud)\n  --domain <endereço>  endereço próprio, ex.: meuclaude.home (precisa de uma entrada no DNS do roteador)\n  --port <n>           porta no computador (padrão: 443 se estiver livre, senão 4748)\n  --allow <lista>      o que o celular pode fazer: permissions, messages, terminal, spawn, none (padrão: permissions)\n  --password-stdin     lê a senha da entrada padrão (automação), em vez de perguntar\n  --no-service         não instala o serviço do anúncio <nome>.local (rode npm run remote:mdns você mesmo)\n  --off                desliga o acesso pelo celular (tira as linhas do .env e o serviço; mantém a CA)": "사용법: npm run remote:setup [-- 옵션]\n\n사용자 이름, 비밀번호, HTTPS로 휴대폰 접속(https://<이름>.local)을 켜요.\n\n  --user <이름>        로그인 사용자 이름(기본값: 시스템 사용자 이름)\n  --name <이름>        주소 <이름>.local (기본값: habblaud)\n  --domain <주소>      직접 정한 주소, 예: myclaude.home (공유기 DNS에 항목이 필요해요)\n  --port <n>           컴퓨터의 포트(기본값: 비어 있으면 443, 아니면 4748)\n  --allow <목록>       휴대폰에서 할 수 있는 것: permissions, messages, terminal, spawn, none (기본값: permissions)\n  --password-stdin     묻지 않고 표준 입력에서 비밀번호를 읽어요(자동화용)\n  --no-service         <이름>.local 알림 서비스를 설치하지 않아요(npm run remote:mdns 를 직접 실행하세요)\n  --off                휴대폰 접속을 꺼요(.env 의 줄과 서비스를 지우고 CA는 남겨요)",
  "falta o valor de {0}": "{0} 값이 없어요",
  "opção desconhecida: {0}": "알 수 없는 옵션: {0}",
  "porta inválida": "잘못된 포트",
  "use pelo menos {0} caracteres": "{0}자 이상 쓰세요",
  "sem espaços no começo ou no fim": "앞뒤에 공백 없이",
  "a senha não pode ser o usuário": "비밀번호를 사용자 이름과 같게 할 수 없어요",
  "sem terminal para perguntar a senha: use --password-stdin": "비밀번호를 물어볼 터미널이 없어요: --password-stdin 을 쓰세요",
  "serviço {0} ligado (log: ~/.habblaud/logs/remote-mdns.log)": "{0} 서비스 켜짐(로그: ~/.habblaud/logs/remote-mdns.log)",
