  " CA local nova (o endereço mudou ou a anterior não tinha restrição de nomes): instale o certificado de novo no celular.": " 새 로컬 CA(주소가 바뀌었거나 이전 CA에 이름 제한이 없었어요): 휴대폰에 인증서를 다시 설치하세요.",
