  "  Primeira vez: aceite o aviso, toque em \"Instale o certificado do Habblaud\" e confie nele": "  처음이라면: 경고를 수락하고 \"Habblaud 인증서 설치\"를 누른 뒤 인증서를 신뢰하세요",
  "    iPhone:  Ajustes > Perfil Baixado > Instalar; depois Ajustes > Geral > Sobre > Ajustes de Confiança de Certificados": "    iPhone:  설정 > 다운로드된 프로파일 > 설치, 그다음 설정 > 일반 > 정보 > 인증서 신뢰 설정",
  "    Android: Configurações > Segurança > Criptografia e credenciais > Instalar certificado > Certificado de CA": "    Android: 설정 > 보안 > 암호화 및 사용자 인증 정보 > 인증서 설치 > CA 인증서",
