  "Seu escritório agora pode virar um prédio numa cidade online, aceso enquanto os seus agentes trabalham.": "이제 사무실이 온라인 도시의 건물이 될 수 있어요. 에이전트가 일하는 동안 불이 켜져요.",
  "Seu escritório vira um prédio numa cidade em pixel art, aceso enquanto os seus agentes trabalham.": "사무실이 픽셀아트 도시의 건물이 돼요. 에이전트가 일하는 동안 불이 켜져요.",
