  "O acesso é liberado aos poucos, em lotes. Avisamos por e-mail quando chegar a sua vez.": "접속은 순서대로 조금씩 열려요. 차례가 되면 이메일로 알려 드릴게요.",
  "Enquanto isso, o Habblaud continua normal e nada do escritório é enviado.": "그동안 Habblaud는 평소처럼 동작하고, 사무실 정보는 아무것도 보내지 않아요.",
  "Entendi": "확인",
  "Chegou a sua vez: crie o seu personagem e entre na cidade.": "차례가 왔어요. 캐릭터를 만들고 도시에 들어가 보세요.",

  // client/src/ui/world/settings-world.ts
  "← Voltar": "← 뒤로",
