  "Dá para ver o prédio por fora, mas ninguém entra.": "건물 바깥은 보이지만 아무도 들어올 수 없어요.",
  "Esconder o país": "국가 숨기기",
  "No lugar da bandeira do país (visto pelo IP da conexão) aparece uma bandeira neutra.": "국기 대신 중립 깃발이 보여요(국가는 접속 IP로 판단해요).",
  "Mostrar o consumo de tokens": "토큰 사용량 표시",
  "Total do dia e da semana do prédio inteiro, só em faixas (até 100 mil, 1 milhão…). Nunca o custo.": "건물 전체의 일간·주간 합계를 구간으로만 보여요(10만까지, 100만까지…). 비용은 절대 보이지 않아요.",
  "Entrar no placar": "순위표 참여",
  "O prédio pode aparecer nos placares de tokens da cidade.": "도시의 토큰 순위표에 내 건물이 나올 수 있어요.",
  "Mostrar as compactações": "컨텍스트 압축 표시",
  "Quando um agente compacta o contexto, a lixeira da sala enche. Sai só o fato, nada do conteúdo.": "에이전트가 컨텍스트를 압축하면 방의 휴지통이 차요. 압축했다는 사실만 보내고 내용은 보내지 않아요.",
  "Habblaud World": "Habblaud World",
  "Só pelo computador": "이 컴퓨터에서만",
  "Sem conta": "계정 없음",
  "Na lista de espera": "대기 중",
  "Liberado": "승인됨",
  "A conta do Habblaud World só pode ser mexida no próprio computador, com o Habblaud em acesso local (bind 127.0.0.1) e aberto por http://localhost.": "Habblaud World 계정은 이 컴퓨터에서만 관리할 수 있어요. Habblaud가 로컬 접속(bind 127.0.0.1)이고 http://localhost 로 열려 있어야 해요.",
  "Já tenho conta": "이미 계정이 있어요",
  "Leve o seu escritório para uma cidade em pixel art: um prédio seu, aceso enquanto os agentes trabalham, e um personagem para passear e visitar os prédios de outras pessoas.": "사무실을 픽셀아트 도시로 옮겨 보세요. 에이전트가 일하는 동안 불이 켜지는 내 건물과, 돌아다니며 다른 사람들의 건물을 구경할 캐릭터가 생겨요.",
  "O acesso é liberado aos poucos: quem cria a conta entra numa lista de espera.": "접속은 조금씩 열려요. 계정을 만들면 대기자 명단에 올라가요.",
  "O que sai do seu computador": "컴퓨터 밖으로 나가는 것",
  "Quem visita o mundo vê, ao vivo, quantos projetos e agentes você está rodando e o que cada personagem está fazendo (trabalhando, esperando, à toa). Ninguém vê quais projetos são, o que os agentes fazem, nem quem você é: só o nickname e o avatar que você escolheu.": "월드에 온 사람들은 내가 프로젝트와 에이전트를 몇 개 돌리고 있는지, 각 캐릭터가 뭘 하는지(작업 중, 대기 중, 쉬는 중)를 실시간으로 봐요. 어떤 프로젝트인지, 에이전트가 뭘 하는지, 내가 누군지는 아무도 몰라요. 보이는 건 내가 고른 닉네임과 아바타뿐이에요.",
  "Sai:": "나가는 것:",
  "o tema do escritório; um andar por sala aberta, com um código aleatório que muda todo dia; de cada agente, se é principal ou subagente, a ferramenta, o status, a aparência, um nome sorteado e a faixa de tarefas concluídas no dia; os tokens do prédio arredondados em faixas (dá para desligar); se você ligar, o fato de um agente ter compactado o contexto; a versão e o commit do Habblaud, com a marca de cópia modificada; e o idioma da interface, só para os e-mails.": "사무실 테마; 열린 방마다 층 하나(매일 바뀌는 무작위 코드 포함); 에이전트마다 메인/서브에이전트 여부, 도구, 상태, 외형, 무작위로 뽑은 이름, 그날 끝낸 작업 수 구간; 구간으로 반올림한 건물 토큰 수(끌 수 있어요); 켜 둔 경우 에이전트가 컨텍스트를 압축했다는 사실; Habblaud 버전과 커밋(수정본 표시 포함); 이메일에만 쓰는 인터페이스 언어.",
  "Nunca sai:": "절대 나가지 않는 것:",
  "caminhos e nomes de projetos, títulos de sessão, comandos, mensagens, código, custo, a sua conta do Claude, o seu e-mail e o nome do computador.": "프로젝트 경로와 이름, 세션 제목, 명령, 메시지, 코드, 비용, Claude 계정, 이메일, 컴퓨터 이름.",
  "Com os dados que saem não dá para saber quem você é nem em que trabalha.": "나가는 데이터로는 내가 누군지, 무슨 일을 하는지 알 수 없어요.",
  "Os agentes trabalham sem você: prédio aceso não quer dizer que você está no computador. Se preferir, use o modo discreto ou feche o prédio a visitas.": "에이전트는 내가 없어도 일해요. 건물에 불이 켜져 있다고 내가 컴퓨터 앞에 있다는 뜻은 아니에요. 원하면 조용 모드를 쓰거나 건물 방문을 닫으세요.",
  "Ver a lista completa": "전체 목록 보기",
  "Pelo menos 12 caracteres. Uma frase longa vale mais do que símbolos; senhas que já vazaram são recusadas.": "12자 이상. 기호보다 긴 문장이 더 안전해요. 유출된 적 있는 비밀번호는 쓸 수 없어요.",
