  "O World só funciona se os prédios forem verdadeiros. Mandar dados inventados quebra os termos e bane a conta.": "World는 건물이 진짜여야 돌아가요. 지어낸 데이터를 보내면 약관 위반이라 계정이 영구 정지돼요.",
