  "Não chegou? Confira o spam ou peça outro. Se este e-mail já tinha conta, a mensagem avisa: aí é só entrar com a senha.": "안 왔나요? 스팸함을 확인하거나 다시 요청하세요. 이미 계정이 있는 이메일이면 메일에 그렇게 적혀 있으니 비밀번호로 로그인하면 돼요.",
