  "De 3 a 20 caracteres: letras de um só alfabeto, números, espaço, _ - e . É o seu nome no mundo e não pode repetir o de ninguém.": "3~20자: 한 가지 문자 체계의 글자, 숫자, 공백, _ - . 를 쓸 수 있어요. 월드에서 쓰는 이름이고 다른 사람과 겹칠 수 없어요.",
  "Dá para trocar uma vez a cada 30 dias.": "30일에 한 번 바꿀 수 있어요.",
  "3 a 20 caracteres; é o nome do seu personagem e fica reservado para você, mesmo na lista de espera. Único no mundo.": "3~20자. 캐릭터 이름이고, 대기 중에도 내 이름으로 예약돼요. 월드에서 하나뿐이에요.",
  "Esse nome já está em uso. Escolha outro.": "이미 쓰는 이름이에요. 다른 이름을 고르세요.",
