  "Escolha um nome novo: a moderação trocou o seu nome de jogador. O nome novo entra na hora, sem esperar os 30 dias.": "새 이름을 고르세요. 운영진이 플레이어 이름을 바꿨어요. 새 이름은 30일을 기다리지 않고 바로 적용돼요.",
  "Escolha 2 ou 3 traços. Os que não combinam com os já escolhidos ficam apagados.": "특성을 2~3개 고르세요. 이미 고른 것과 어울리지 않는 특성은 흐리게 보여요.",
  "Aparece no seu perfil, traduzida para quem lê. No mundo não há texto livre além do nome.": "프로필에 보이고, 읽는 사람의 언어로 번역돼요. 월드에는 이름 말고 자유 입력 텍스트가 없어요.",
  "Criar personagem": "캐릭터 만들기",
