  "Modo do prédio": "건물 모드",
  "Ao vivo: andares, contadores e o que cada personagem está fazendo, em tempo real. Discreto: só aceso ou apagado e o número de andares.": "실시간: 층, 카운터, 각 캐릭터가 하는 일을 실시간으로 보여요. 조용: 불이 켜졌는지 꺼졌는지와 층수만 보여요.",
  "País: escondido (aparece uma bandeira neutra).": "국가: 숨김(중립 깃발이 보여요).",
  "País visto na última conexão: {0}.": "마지막 접속 때 확인된 국가: {0}.",
  "País: aparece depois da primeira conexão com o mundo.": "국가: 월드에 처음 접속한 뒤에 보여요.",
  "As mudanças valem na hora.": "바꾸면 바로 적용돼요.",
  "Até 3 por conta. Revogar desconecta o dispositivo na hora; para voltar, ele entra de novo com a senha.": "계정당 최대 3대. 연결을 해제하면 그 기기는 바로 로그아웃되고, 다시 쓰려면 비밀번호로 로그인해야 해요.",
