  // client/src/ui/world/world-model.ts
  "A senha precisa ter pelo menos 12 caracteres.": "비밀번호는 12자 이상이어야 해요.",
  "A senha pode ter no máximo 128 caracteres.": "비밀번호는 최대 128자예요.",
  "A senha não pode ser o seu e-mail.": "이메일을 비밀번호로 쓸 수 없어요.",
  "A senha não pode ser só uma repetição (como \"aaaaaaaaaaaa\").": "같은 글자만 반복한 비밀번호는 쓸 수 없어요(\"aaaaaaaaaaaa\"처럼).",
  "O nome precisa ter de 3 a 20 caracteres.": "이름은 3~20자여야 해요.",
  "Use só letras, números, espaço, _ - e . no nome.": "이름에는 글자, 숫자, 공백, _ - . 만 쓸 수 있어요.",
  "Use letras de um só alfabeto no nome.": "이름에는 한 가지 문자 체계의 글자만 쓰세요.",
  "Tire do nome os caracteres invisíveis e os espaços especiais.": "이름에서 보이지 않는 문자와 특수 공백을 빼 주세요.",
  "O nome precisa ter pelo menos uma letra.": "이름에 글자가 하나 이상 있어야 해요.",
  "Este nome é reservado. Escolha outro.": "예약된 이름이에요. 다른 이름을 고르세요.",
  "Código errado ou vencido. Confira o e-mail ou peça outro código.": "코드가 틀렸거나 만료됐어요. 이메일을 확인하거나 코드를 다시 요청하세요.",
  "E-mail ou senha não conferem.": "이메일 또는 비밀번호가 맞지 않아요.",
  "Falta confirmar o e-mail: mandamos um código novo.": "아직 이메일 인증을 안 했어요. 새 코드를 보냈어요.",
  "Esta conta foi banida do Habblaud World. Para recorrer, responda ao e-mail do banimento.": "이 계정은 Habblaud World에서 영구 정지됐어요. 이의 신청은 정지 안내 이메일에 답장하세요.",
  "Este nome já está em uso no mundo. Escolha outro.": "월드에서 이미 쓰는 이름이에요. 다른 이름을 고르세요.",
  "Nome inválido: de 3 a 20 caracteres, com letras de um só alfabeto, números, espaço, _ - e .": "잘못된 이름: 3~20자, 한 가지 문자 체계의 글자, 숫자, 공백, _ - . 만 쓸 수 있어요.",
  "Este nome não é permitido. Escolha outro.": "쓸 수 없는 이름이에요. 다른 이름을 고르세요.",
  "O Habblaud World não está ligado neste Habblaud (HABBLAUD_WORLD_URL recusada; veja o log do servidor).": "이 Habblaud에서는 Habblaud World가 켜져 있지 않아요(HABBLAUD_WORLD_URL 거부됨, 서버 로그를 확인하세요).",
  "Muitas tentativas seguidas. Espere alguns minutos e tente de novo.": "시도가 너무 많아요. 몇 분 뒤에 다시 해 보세요.",
  "O servidor do Habblaud World não respondeu. Tente de novo em instantes.": "Habblaud World 서버가 응답하지 않아요. 잠시 뒤에 다시 해 보세요.",
  "A conta do World só pode ser mexida pelo próprio computador, com o Habblaud aberto em localhost.": "World 계정은 이 컴퓨터에서 Habblaud를 localhost로 열었을 때만 관리할 수 있어요.",
  "Esta conta está suspensa no Habblaud World por enquanto.": "이 계정은 지금 Habblaud World에서 일시 정지 상태예요.",
  "A sessão do Habblaud World neste computador terminou. Entre de novo.": "이 컴퓨터의 Habblaud World 세션이 끝났어요. 다시 로그인하세요.",
  "O nome só pode ser trocado uma vez a cada 30 dias.": "이름은 30일에 한 번만 바꿀 수 있어요.",
  "A senha precisa ter de 12 a 128 caracteres.": "비밀번호는 12~128자여야 해요.",
  "Senha fraca: não use o e-mail, o nome de jogador nem só repetição.": "약한 비밀번호예요. 이메일, 플레이어 이름, 단순 반복은 쓰지 마세요.",
  "Esta senha aparece em vazamentos de dados conhecidos. Escolha outra.": "알려진 유출 데이터에 있는 비밀번호예요. 다른 비밀번호를 고르세요.",
  "E-mail inválido. Confira o endereço.": "잘못된 이메일이에요. 주소를 확인하세요.",
  "A verificação anti-robô não passou. Tente de novo em instantes.": "봇 확인을 통과하지 못했어요. 잠시 뒤에 다시 해 보세요.",
  "Esta conta já tem 3 computadores; revogue um em Dispositivos.": "이 계정에는 이미 컴퓨터가 3대 있어요. 기기에서 하나를 연결 해제하세요.",
  "Crie o personagem primeiro.": "캐릭터를 먼저 만드세요.",
  "O Habblaud World está em manutenção. Tente de novo mais tarde.": "Habblaud World 점검 중이에요. 나중에 다시 해 보세요.",
  "O servidor do mundo teve um erro; tente de novo.": "월드 서버에 오류가 났어요. 다시 해 보세요.",
  "Este dispositivo não está mais na conta.": "이 기기는 더 이상 계정에 없어요.",
  "O servidor do Habblaud World não encontrou o que foi pedido.": "Habblaud World 서버에서 요청한 것을 찾지 못했어요.",
  "O pedido saiu num formato que o servidor não aceita. Atualize o Habblaud e tente de novo.": "서버가 받지 않는 형식으로 요청을 보냈어요. Habblaud를 업데이트하고 다시 해 보세요.",
  "O servidor do Habblaud World respondeu algo inesperado. Tente de novo em instantes.": "Habblaud World 서버가 예상하지 못한 응답을 보냈어요. 잠시 뒤에 다시 해 보세요.",
  "Não deu para gravar a sessão neste computador: ela vale só até o Habblaud reiniciar.": "이 컴퓨터에 세션을 저장하지 못했어요. Habblaud를 다시 시작하기 전까지만 유지돼요.",
  "A conta do World só pode ser mexida com o Habblaud acessível apenas pelo próprio computador (acesso local, bind 127.0.0.1).": "World 계정은 Habblaud를 이 컴퓨터에서만 접속할 수 있을 때(로컬 접속, bind 127.0.0.1)만 관리할 수 있어요.",
  "O servidor recusou o e-mail ou a senha. A senha precisa ter de 12 a 128 caracteres e não pode estar numa lista de senhas vazadas.": "서버가 이메일 또는 비밀번호를 거부했어요. 비밀번호는 12~128자여야 하고 유출된 비밀번호 목록에 없어야 해요.",
  "O servidor recusou o personagem. Confira o nome, os traços (2 ou 3) e a frase de apresentação.": "서버가 캐릭터를 거부했어요. 이름, 특성(2~3개), 자기소개 문구를 확인하세요.",
  "O servidor recusou as opções de visibilidade.": "서버가 공개 범위 설정을 거부했어요.",
  "O servidor recusou o pedido. Confira os dados e tente de novo.": "서버가 요청을 거부했어요. 입력한 내용을 확인하고 다시 해 보세요.",
  "Algo deu errado. Tente de novo em instantes.": "문제가 생겼어요. 잠시 뒤에 다시 해 보세요.",
