  "Chegue perto da porta de um prédio e aperte E.": "건물 문 가까이 가서 E를 누르세요.",
  "Devagar: o mundo pediu um tempo entre as ações.": "천천히요. 월드가 행동 사이에 잠깐 쉬어 달래요.",
  "Aviso do Habblaud World.": "Habblaud World 알림.",
  "Minimapa: clique para levar a câmera até lá": "미니맵: 클릭하면 카메라가 그곳으로 가요",
  "Sem conexão com o Habblaud World agora; o Habblaud tenta de novo sozinho.": "지금 Habblaud World에 연결되지 않아요. Habblaud가 알아서 다시 시도해요.",
  "Essa pessoa não está mais por perto.": "그 사람은 이제 근처에 없어요.",
  "Você ficou um bom tempo parado e saiu da rua: ande para voltar.": "한참 가만히 있어서 거리에서 빠졌어요. 움직이면 돌아와요.",
  "A área está cheia: só os jogadores mais perto aparecem.": "이 구역이 꽉 찼어요. 가장 가까운 플레이어만 보여요.",
  "Você ficou um tempo parado.": "한동안 가만히 있었어요.",
  "O Habblaud World vai reiniciar: a conexão cai e volta sozinha.": "Habblaud World가 재시작해요. 연결이 끊겼다가 알아서 돌아와요.",
  "Sua conta saiu do mundo: o prédio volta com \"Voltar ao mundo\", em Configurações.": "계정이 월드에서 나갔어요. 설정의 \"월드로 돌아가기\"로 건물을 되돌릴 수 있어요.",
  "Entrar (E)": "들어가기 (E)",
  "entrar": "들어가기",
  "Sair do prédio": "나가기",
  "Ver como os outros veem": "남들 눈으로 보기",
  "Entrar no seu prédio pela cidade e ver o que quem visita vê (sem nada do escritório real)": "도시에서 내 건물에 들어가 방문자가 보는 화면을 봐요(실제 사무실 정보는 없어요)",
  "Avisar quando alguém visitar": "누가 방문하면 알림",
  "Um aviso quando o primeiro visitante entra no seu prédio. Você vê só quantos estão lá dentro, nunca quem.": "첫 방문자가 건물에 들어오면 알려 줘요. 안에 몇 명 있는지만 보이고, 누군지는 보이지 않아요.",
  "Alguém entrou no seu prédio no Habblaud World.": "누군가 Habblaud World의 내 건물에 들어왔어요.",
  "1 visitante agora": "지금 방문자 1명",
  "{0} visitantes agora": "지금 방문자 {0}명",
  "Este prédio não está no mundo agora.": "이 건물은 지금 월드에 없어요.",
  "O prédio saiu do mundo: você voltou para a rua.": "건물이 월드에서 빠져서 거리로 돌아왔어요.",
  "Chegue mais perto da porta para entrar.": "들어가려면 문에 더 가까이 가세요.",
  "O prédio fechou a visitas: você voltou para a rua.": "건물이 방문을 닫아서 거리로 돌아왔어요.",
  "Este prédio está fechado a visitas.": "이 건물은 방문을 받지 않아요.",
  "Você não pode mais ficar neste prédio: voltou para a rua.": "이 건물에 더 머물 수 없어서 거리로 돌아왔어요.",
  "Você não pode entrar neste prédio.": "이 건물에는 들어갈 수 없어요.",
  "O prédio está lotado (20 visitantes). Tente daqui a pouco.": "건물이 꽉 찼어요(방문자 20명). 조금 뒤에 다시 해 보세요.",
  "Esperando o dono": "주인을 기다리는 중",
