  "Salas do prédio": "건물의 방",
  "Só o nome, o papel, a ferramenta e o status de cada agente: o resto do escritório não sai do computador do dono.": "에이전트마다 이름, 역할, 도구, 상태만 보여요. 나머지 사무실 정보는 주인의 컴퓨터 밖으로 나가지 않아요.",
  "Sair pelo elevador": "엘리베이터로 나가기",
  "elevador": "엘리베이터",
  "sair": "나가기",
  "Saindo do prédio…": "건물에서 나가는 중…",
  "apagado": "불 꺼짐",
  "discreto": "조용",
  "modo discreto": "조용 모드",
  "Seu prédio, como os outros veem": "남들이 보는 내 건물",
  "Prédio de {0}": "{0}의 건물",
  "esperando o dono": "주인을 기다리는 중",
  "de olho no terminal": "터미널 지켜보는 중",
  "Prédio apagado: o dono pausou ou não está com o Habblaud aberto. As salas ficam escuras e vazias.": "불 꺼진 건물: 주인이 일시정지했거나 Habblaud를 열어 두지 않았어요. 방이 어둡고 비어 있어요.",
  "Modo discreto: o dono não mostra os agentes. As salas aparecem vazias, com a luz acesa.": "조용 모드: 주인이 에이전트를 공개하지 않아요. 방은 불이 켜진 채로 비어 보여요.",
  "O mundo está em manutenção; tentamos de novo em instantes.": "월드 점검 중이에요. 잠시 뒤에 다시 시도할게요.",
  "Conta excluída": "계정 삭제됨",
  "A conta do Habblaud World foi excluída: o prédio e o perfil saíram do mundo e nada mais sai deste computador.": "Habblaud World 계정이 삭제됐어요. 건물과 프로필은 월드에서 빠졌고, 이 컴퓨터에서는 더 이상 아무것도 나가지 않아요.",
  "Habblaud World: desligado (HABBLAUD_WORLD={0}).": "Habblaud World: 꺼짐 (HABBLAUD_WORLD={0}).",
  "Habblaud World: ligado: {0}": "Habblaud World: 켜짐: {0}",
  "Habblaud World: ligado: {0} (padrão)": "Habblaud World: 켜짐: {0} (기본값)",
  "HABBLAUD_WORLD_URL recusada": "HABBLAUD_WORLD_URL 거부됨",
  "Habblaud World: desligado ({0}).": "Habblaud World: 꺼짐 ({0}).",
  "A conta do Habblaud World foi excluída. O prédio e o perfil saíram do mundo na hora; o resto é apagado do banco em 7 dias e dos backups em até 30.": "Habblaud World 계정이 삭제됐어요. 건물과 프로필은 바로 월드에서 빠졌고, 나머지는 7일 안에 데이터베이스에서, 30일 안에 백업에서 지워져요.",
  "Habblaud World: conta excluída; a sessão e o world.json foram apagados deste computador.": "Habblaud World: 계정 삭제됨. 세션과 world.json을 이 컴퓨터에서 지웠어요.",
  "os dados da conta só saem pela própria página do Habblaud": "계정 데이터는 Habblaud 페이지에서만 내려받을 수 있어요",
  "a conta, o personagem, os likes dados e recebidos, os bloqueios, as denúncias feitas e os dispositivos são apagados do banco.": "계정, 캐릭터, 주고받은 좋아요, 차단, 내가 한 신고, 기기 정보가 데이터베이스에서 지워져요.",
  "Abre um e-mail para {0}: conte o que aconteceu, e uma pessoa revê o caso.": "{0}(으)로 보낼 이메일이 열려요. 무슨 일이 있었는지 적어 주면 사람이 직접 검토해요.",
  "Abre um e-mail para {0}: se for engano, uma pessoa revê os números e tira o selo.": "{0}(으)로 보낼 이메일이 열려요. 착오라면 사람이 수치를 검토하고 표시를 없애요.",
  "Avisar por e-mail antes de retirar meu prédio por inatividade": "비활동으로 건물이 철거되기 전에 이메일로 알림",
  "Baixar meus dados": "내 데이터 내려받기",
  "Conta e dados": "계정과 데이터",
  "Contestar por e-mail": "이메일로 이의 제기",
  "Dá para baixar os dados uma vez por dia. Tente de novo amanhã.": "데이터는 하루에 한 번 내려받을 수 있어요. 내일 다시 해 보세요.",
  "Dúvidas ou pedidos sobre os seus dados: {0}.": "데이터 관련 문의나 요청: {0}.",
  "Em 7 dias:": "7일 안에:",
  "Em até 30 dias:": "30일 안에:",
  "Em manutenção": "점검 중",
  "Excluindo…": "삭제 중…",
  "Excluir a conta tira você do Habblaud World:": "계정을 삭제하면 Habblaud World에서 빠져요:",
  "Excluir a conta": "계정 삭제하기",
  "Excluir conta": "계정 삭제",
  "Excluir conta…": "계정 삭제…",
  "Mandamos um código de 6 dígitos para {0}. Digite o código para excluir a conta.": "{0}(으)로 6자리 코드를 보냈어요. 계정을 삭제하려면 코드를 입력하세요.",
  "Mandar o código": "코드 보내기",
  "Na hora:": "즉시:",
  "Não verificado": "미확인",
  "O aviso de inatividade fica disponível depois de criar o personagem.": "비활동 알림은 캐릭터를 만든 뒤에 쓸 수 있어요.",
  "O mundo marcou o seu prédio como \"não verificado\": os números pareceram fora do normal e estão em revisão. Ele continua no mundo, mas fora de placares e destaques.": "월드가 내 건물을 \"미확인\"으로 표시했어요. 수치가 이상해 보여서 검토 중이에요. 월드에는 그대로 있지만 순위표와 추천에서는 빠져요.",
  "o prédio e o perfil somem do mundo, e este computador sai da conta.": "건물과 프로필이 월드에서 사라지고, 이 컴퓨터는 계정에서 로그아웃돼요.",
  "Os números deste prédio pareceram fora do normal e estão em revisão; enquanto isso, ele fica fora de placares e destaques.": "이 건물의 수치가 이상해 보여서 검토 중이에요. 그동안 순위표와 추천에서 빠져요.",
  "Para confirmar, mandamos um código de 6 dígitos para o e-mail da conta ({0}).": "확인을 위해 계정 이메일({0})로 6자리 코드를 보내요.",
  "Pronto: o arquivo {0} foi para a pasta de downloads.": "완료: {0} 파일을 다운로드 폴더에 저장했어요.",
  "Recorrer por e-mail": "이메일로 이의 신청",
  "Se quiser guardar uma cópia, baixe os seus dados antes.": "사본을 남기고 싶으면 먼저 데이터를 내려받으세요.",
  "Sem notícias deste Habblaud por 7 dias, o prédio some do mapa e, 30 dias depois, é retirado. O e-mail chega 3 dias antes da retirada.": "이 Habblaud에서 7일 동안 소식이 없으면 건물이 지도에서 사라지고, 그로부터 30일 뒤 철거돼요. 이메일은 철거 3일 전에 가요.",
  "Seus dados": "내 데이터",
  "somem também dos backups.": "백업에서도 지워져요.",
  "Tem certeza? O prédio e o perfil saem do mundo assim que você digitar o código.": "정말 삭제할까요? 코드를 입력하는 즉시 건물과 프로필이 월드에서 빠져요.",
  "Um arquivo JSON com o que o Habblaud World guarda da sua conta: e-mail, datas, personagem, visibilidade, dispositivos, prédio, likes dados, bloqueios e denúncias feitas. Dá para baixar uma vez por dia.": "Habblaud World가 내 계정에 대해 보관하는 정보를 담은 JSON 파일이에요: 이메일, 날짜, 캐릭터, 공개 범위, 기기, 건물, 내가 준 좋아요, 차단, 내가 한 신고. 하루에 한 번 내려받을 수 있어요.",
  "O pacote contradiz o anterior de um jeito que o Habblaud não produz: o mundo o descartou, e o prédio fica com o último aceito. As próximas remessas vão normalmente.": "이 패킷은 Habblaud가 만들 수 없는 방식으로 이전 패킷과 어긋나요. 월드가 버렸고, 건물은 마지막으로 받은 상태를 유지해요. 다음 전송은 정상으로 가요.",

